"""Short French lessons explaining the themes already available in Slovo.

Explanations and self-checks are pedagogical supplements, not PDF quotations.
Example vocabulary and audio are resolved from the existing catalog.
"""


def lesson(slug, title, category, goal, sections, examples, question, answer, tip):
    return dict(slug=slug, title=title, category=category, goal=goal,
                sections=sections, examples=examples, question=question,
                answer=answer, tip=tip)


